# Etiquetas «Categoría · fecha» y «Fuente: …»
CAT = {"Precios": ("Prices", "Prix", "Preços"), "Mercados": ("Markets", "Marchés", "Mercados"),
       "Normativa": ("Regulation", "Réglementation", "Regulamentação"), "Novedades": ("News", "Nouveautés", "Novidades")}
MES = {"oct": ("Oct", "oct.", "out."), "nov": ("Nov", "nov.", "nov.")}
def _f(fecha):
    d, m, y = fecha.split()
    return tuple(f"{d} {MES[m][i]} {y}" for i in range(3))
